import { createRequire } from 'node:module';
import fs from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const cfg = JSON.parse(fs.readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json', 'utf8'));
const browser = await chromium.launch(cfg.browser.launchOptions);
for (const mode of [{name:'desktop', viewport:{width:1280,height:720}, isMobile:false, hasTouch:false}, {name:'mobile', viewport:{width:390,height:844}, isMobile:true, hasTouch:true}]) {
  const context = await browser.newContext(mode);
  const page = await context.newPage();
  const errors = [], failed = [];
  page.on('pageerror', e => errors.push(e.message));
  page.on('requestfailed', r => failed.push(`${r.url()}: ${r.failure()?.errorText}`));
  await page.goto('http://127.0.0.1:3000');
  await page.waitForTimeout(600);
  await page.locator('#startButton').click({force:true});
  await page.waitForTimeout(1200);
  const initial = await page.locator('#ammoText').textContent();
  if (mode.isMobile) {
    await page.locator('#fireButton').dispatchEvent('pointerdown', {pointerId:1, pointerType:'touch', button:0});
    await page.waitForTimeout(100);
    await page.locator('#fireButton').dispatchEvent('pointerup', {pointerId:1, pointerType:'touch', button:0});
  } else {
    await page.keyboard.press('3');
    await page.mouse.click(640, 360);
    await page.mouse.down(); await page.waitForTimeout(180); await page.mouse.up();
  }
  await page.waitForTimeout(200);
  const weaponAfter = await page.locator('#weaponText').textContent();
  const ammoAfter = await page.locator('#ammoText').textContent();
  await page.locator('#pauseButton').click();
  const pauseShown = await page.locator('#pauseScreen').isVisible();
  await page.locator('#resumeButton').click();
  await page.locator('#inventoryButton').click({force:true});
  const inventoryShown = await page.locator('#inventoryScreen').isVisible();
  await page.locator('[data-weapon="shotgun"]').click();
  const inventoryWeapon = await page.locator('#weaponText').textContent();
  let raf = 0;
  await page.evaluate(() => { window.__raf=0; const f=()=>{window.__raf++;requestAnimationFrame(f)}; requestAnimationFrame(f); });
  await page.waitForTimeout(1500);
  raf = await page.evaluate(() => window.__raf);
  const boxes = await page.evaluate(() => Object.fromEntries(['#vitals','#minimap','#pauseButton','#joystick','#touchActions','#fireButton','#weaponText'].map(sel => {const e=document.querySelector(sel); if(!e)return [sel,null]; const r=e.getBoundingClientRect();return [sel,{x:Math.round(r.x),y:Math.round(r.y),w:Math.round(r.width),h:Math.round(r.height),display:getComputedStyle(e).display}]})));
  await page.screenshot({path:`/tmp/opencode/zombie-${mode.name}-tested.png`});
  console.log(JSON.stringify({mode:mode.name,initial,weaponAfter,ammoAfter,pauseShown,inventoryShown,inventoryWeapon,raf,errors,failed,boxes}));
  await context.close();
}
await browser.close();
EOF

